PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL := FALSE;
    ValveOut : BOOL := FALSE;
END_VAR
VAR
    PumpOnLimit : INT := 10;
    PumpOffLimit : INT := 90;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := Level >= PumpOffLimit, PT := T#1s);

IF Level <= PumpOnLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= PumpOffLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

IF SafetyTimer.Q THEN
    PumpIn := FALSE;
END_IF;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL := FALSE;
    ValveOut : BOOL := FALSE;
END_VAR
VAR
    prev_PumpIn : BOOL := FALSE;
    prev_ValveOut : BOOL := FALSE;
    Hyst_Limit : INT := 10;
    Hyst_High : INT := 90;
END_VAR

IF NOT prev_PumpIn AND PumpIn THEN
    IF Level >= Hyst_High THEN
        ValveOut := TRUE;
    ELSE
        ValveOut := FALSE;
    END_IF;
ELSIF NOT prev_ValveOut AND ValveOut THEN
    IF Level <= Hyst_Limit THEN
        PumpIn := TRUE;
    ELSE
        PumpIn := FALSE;
    END_IF;
END_IF;

prev_PumpIn := PumpIn;
prev_ValveOut := ValveOut;
END_PROGRAM

