PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL := FALSE;
    DoorB : BOOL := FALSE;
END_VAR

VAR
    T_A : TON;
    T_B : TON;
    Prev_OpenA_Cmd : BOOL := FALSE;
    Prev_OpenB_Cmd : BOOL := FALSE;
END_VAR

IF NOT (Prev_OpenA_Cmd OR Prev_OpenB_Cmd) THEN
    IF OpenA_Cmd THEN
        DoorA := TRUE;
        DoorB := FALSE;
        T_A(IN := TRUE, PT := T#3s);
        T_B(IN := FALSE);
    ELSIF OpenB_Cmd THEN
        DoorA := FALSE;
        DoorB := TRUE;
        T_B(IN := TRUE, PT := T#3s);
        T_A(IN := FALSE);
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
        T_A(IN := FALSE);
        T_B(IN := FALSE);
    END_IF;
ELSIF Prev_OpenA_Cmd AND NOT OpenA_Cmd THEN
    DoorA := FALSE;
    T_A(IN := FALSE);
ELSIF Prev_OpenB_Cmd AND NOT OpenB_Cmd THEN
    DoorB := FALSE;
    T_B(IN := FALSE);
END_IF;

Prev_OpenA_Cmd := OpenA_Cmd;
Prev_OpenB_Cmd := OpenB_Cmd;
END_PROGRAM

