PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    TimerA : TON;
    TimerB : TON;
END_VAR

DoorA := FALSE;
DoorB := FALSE;

IF OpenA_Cmd THEN
    IF NOT OpenB_Cmd THEN
        DoorA := TRUE;
        TimerA(IN := TRUE, PT := T#1s);
    ELSE
        DoorA := FALSE;
        TimerA(IN := FALSE);
    END_IF;
ELSIF OpenB_Cmd THEN
    IF NOT OpenA_Cmd THEN
        DoorB := TRUE;
        TimerB(IN := TRUE, PT := T#1s);
    ELSE
        DoorB := FALSE;
        TimerB(IN := FALSE);
    END_IF;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
    TimerA(IN := FALSE);
    TimerB(IN := FALSE);
END_IF;

IF TimerA.Q AND TimerB.Q THEN
    DoorA := FALSE;
    DoorB := FALSE;
    TimerA(IN := FALSE);
    TimerB(IN := FALSE);
END_IF;

IF TimerA.Q THEN
    DoorA := TRUE;
    DoorB := FALSE;
END_IF;

IF TimerB.Q THEN
    DoorA := FALSE;
    DoorB := TRUE;
END_IF;
END_PROGRAM

PROGRAM conveyor_ctrl
