            State := 1;
        END_IF;

    1: // Cars Yellow
        CarGreen := FALSE;
        CarYellow := TRUE;
        CarRed := FALSE;
        PedWalk := FALSE;
        IF T_Yellow.Q THEN
            State := 2;
        END_IF;

    2: // Cars Red/Ped Walk
        CarGreen := FALSE;
        CarYellow := FALSE;
        CarRed := TRUE;
        PedWalk := TRUE;
        IF T_Walk.Q THEN
            State := 0;
        END_IF;
END_CASE;

T_Green(IN := State = 0);
T_Yellow(IN := State = 1);
T_Walk(IN := State = 2);

CarGreen := T_Green.Q AND (State = 0);
CarYellow := T_Yellow.Q AND (State = 1);
CarRed := NOT (CarGreen OR CarYellow);
