    Ignition : BOOL := FALSE;
END_VAR

VAR
    State : INT := 0;
    PurgeTimer : TON;
    IgnitionTimer : TON;
END_VAR

CASE State OF
    0: // Off
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;

    1: // Pre-purge
        PurgeTimer(IN := TRUE, PT := T#3s);
        IF PurgeTimer.Q THEN
            State := 2;
        END_IF;

    2: // Ignition trial
        IgnitionTimer(IN := TRUE, PT := T#2s);
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF Flame THEN
            State := 3;
        ELSIF IgnitionTimer.Q OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
