PROGRAM GateControl
VAR
    OpenCmd, CloseCmd, OpenLimit, CloseLimit, Obstruction : BOOL;
    MotorOpen, MotorClose : BOOL;
    State : INT;
    OpeningTimer, ClosingTimer : TON;
END_VAR

CASE State OF
    0: -- Idle
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
            OpeningTimer(IN := TRUE, PT := T#5s);
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := 2;
            ClosingTimer(IN := TRUE, PT := T#5s);
        END_IF;

    1: -- Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit THEN
            State := 0;
            OpeningTimer(IN := FALSE);
        ELSIF CloseCmd THEN
            State := 2;
            OpeningTimer(IN := FALSE);
            ClosingTimer(IN := TRUE, PT := T#5s);
        ELSIF Obstruction THEN
            State := 0;
            OpeningTimer(IN := FALSE);
        END_IF;

    2: -- Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit THEN
            State := 0;
            ClosingTimer(IN := FALSE);
        ELSIF OpenCmd THEN
            State := 1;
            ClosingTimer(IN := FALSE);
            OpeningTimer(IN := TRUE, PT := T#5s);
        ELSIF Obstruction THEN
            State := 0;
            ClosingTimer(IN := FALSE);
        END_IF;
END_CASE;

IF State = 1 THEN
    OpeningTimer(IN := TRUE);
ELSIF State = 2 THEN
    ClosingTimer(IN := TRUE);
ELSE
    OpeningTimer(IN := FALSE);
    ClosingTimer(IN := FALSE);
END_IF;

MotorOpen := MotorOpen AND NOT Obstruction;
MotorClose := MotorClose AND NOT Obstruction;
END_PROGRAM

