    0:
        IF StartPB AND NOT EStopTimer.Q THEN
            State := 1;
            C1 := FALSE;
            C2 := FALSE;
            C3 := TRUE;
        END_IF;
    1:
        IF SeqTimer.Q THEN
            State := 2;
            C1 := FALSE;
            C2 := TRUE;
            C3 := TRUE;
        ELSEIF StopPB OR NOT EStopTimer.Q THEN
            State := 0;
            C1 := FALSE;
            C2 := FALSE;
            C3 := FALSE;
        END_IF;
        SeqTimer(IN := TRUE);
    2:
        IF SeqTimer.Q THEN
            State := 3;
            C1 := TRUE;
            C2 := TRUE;
            C3 := TRUE;
        ELSEIF StopPB OR NOT EStopTimer.Q THEN
            State := 0;
            C1 := FALSE;
            C2 := FALSE;
            C3 := FALSE;
        END_IF;
        SeqTimer(IN := TRUE);
    3:
        IF StopPB OR NOT EStopTimer.Q THEN
            State := 0;
            C1 := FALSE;
            C2 := FALSE;
            C3 := FALSE;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    TimerC3 : TON;
    TimerC2 : TON;
    PT_SEQ : TIME := T#2s;
END_VAR

TimerC3(IN := NOT EStop AND NOT StopPB, PT := PT_SEQ);
TimerC2(IN := NOT EStop AND NOT StopPB AND TimerC3.Q, PT := PT_SEQ);

CASE State OF
    0:
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;
    1:
        IF TimerC3.Q THEN
            State := 2;
        END_IF;
    2:
        IF TimerC2.Q THEN
            State := 3;
        END_IF;
    3:
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

C1 := (State >= 3) AND NOT EStop AND NOT StopPB;
C2 := (State >= 2) AND NOT EStop AND NOT StopPB;
C3 := (State >= 1) AND NOT EStop AND NOT StopPB;

END_PROGRAM

